pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {B} from "../src/B.sol";

contract InvMutTest is Test {
    B c;
    function setUp() public { c = new B(); }
    function testFuzz_property(uint256 amount, address caller) public {
        amount = bound(amount, 1, address(this).balance / 2);
        vm.assume(caller != c.owner());
        vm.assume(caller != address(c));
        vm.assume(caller != address(this));

        uint256 ownerBefore = c.owner().balance;
        vm.deal(caller, amount);
        vm.prank(caller);
        try c.go{value: amount}() {
            uint256 ownerAfter = c.owner().balance;
            assertTrue(ownerAfter >= ownerBefore + amount);
        } catch {
        }
    }
}
